(1, 'SPU20260001', '波司登男士长款羽绒服', '2026新款 含绒量90% 防风防水 保暖至-30℃', 2, 1, 1, 'physical', '[\"{{SITE_URL}}/storage/uploads/images/20260414/69ddaf46c33e8.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69ddaf9090e23.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69ddaf9096c3c.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69ddaf909bc6e.jpg\"]', '', '波司登经典长款羽绒服，采用90%白鸭绒填充，含绒量高，保暖性极佳，适合极寒天气穿着。面料防风防水，穿着舒适。', '<p><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69ddb007cb318.jpg\" alt=\"\" data-href=\"\" style=\"\"/><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69ddb007e13db.jpg\" alt=\"\" data-href=\"\" style=\"\"/><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69ddaf9096c3c.jpg\" alt=\"\" data-href=\"\" style=\"\"/><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69ddb007c62b5.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p>', 699.00, 1299.00, 580, 1280, 35600, 'on_sale', 1, 1, 0, 1, 1, '2026-04-14 08:00:00', '2026-04-14 11:22:44', NULL),
(2, 'SPU20260002', '雅鹿男士短款羽绒服', '轻薄保暖 90绒 时尚休闲 多色可选', 2, 2, 1, 'physical', '[\"{{SITE_URL}}/storage/uploads/images/20260414/69de427d9f576.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69de427dc1217.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69de427d97cd4.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69de427da77a0.jpg\"]', '', '雅鹿轻薄短款羽绒服，填充90%灰鸭绒，轻盈不臃肿，日常通勤首选，多种颜色可供选择。', '<p><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69de427dc1217.jpg\" alt=\"\" data-href=\"\" style=\"\"/><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69de427da77a0.jpg\" alt=\"\" data-href=\"\" style=\"\"/><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69de427d9f576.jpg\" alt=\"\" data-href=\"\" style=\"\"/><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69de427d97cd4.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p>', 399.00, 449.00, 800, 2100, 48200, 'on_sale', 2, 0, 1, 1, 1, '2026-04-14 08:00:00', '2026-04-14 21:35:01', NULL),
(3, 'SPU20260003', '波司登男士连帽羽绒服', '鹅绒填充 含绒量95% 极寒版 轻奢工艺', 2, 1, 1, 'physical', '[\"{{SITE_URL}}/storage/uploads/images/20260414/69de1ec2b477f.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69de1ec29b233.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69de1ec2d6ba1.jpg\", \"{{SITE_URL}}/storage/uploads/images/20260414/69de1ec28cf3f.jpg\"]', '', '波司登旗舰款连帽羽绒服，95%白鹅绒填充，蓬松度高达800+，零下40度极寒保障，奢华舒适。', '<p><img src=\"{{SITE_URL}}/storage/uploads/images/20260414/69de5d77431dd.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p>', 1299.00, 1299.00, 10656, 680, 22000, 'on_sale', 3, 1, 0, 0, 1, '2026-04-14 08:00:00', '2026-04-14 19:04:07', NULL),
